import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Обрезка изображения занимает меньше минуты, когда знаешь шаги. Вы загружаете фото, перетаскиваете рамку вокруг нужной части и скачиваете результат.</p>\n<p>Эта инструкция проведёт вас через весь процесс. В ней — выбор соотношения сторон, использование сетки для лучшего кадрирования, проверка размера на выходе и выбор правильного формата экспорта.</p>\n<p>К концу вы сможете чисто обрезать фото профиля, баннер, скриншот или документ на любом устройстве. Сохраните исходный файл, пока не проверите скачанный результат.</p>\n<h2 id=\"before-you-start\">Перед началом: сначала выберите место назначения</h2>\n<p>Решите, где будет жить обрезанное изображение, прежде чем открывать инструмент. Фото профиля нуждается в квадрате, баннеру нужен широкий прямоугольник, а печати — определённая пропорция.</p>\n<p>Место назначения определяет соотношение сторон, а соотношение определяет форму рамки выделения. Начало с неверной формы означает повторную обрезку позже.</p>\n<p>Используйте исходное фото, а не сжатую или отредактированную копию. Обрезка из наилучшего доступного источника сохраняет сохранённые пиксели максимально резкими.</p>\n<p>Откройте в браузере <a href=\"/ru/obrezat-izobrazhenie/\">инструмент обрезки изображений</a>. Всё работает локально, поэтому ваше фото никогда не загружается на сервер.</p>\n<h2 id=\"step-by-step\">Обрезка изображения за пять шагов</h2>\n<p>Процесс одинаков для фото, скриншота или отсканированного документа. Загрузите, кадрируйте, проверьте, экспортируйте и убедитесь в скачанном файле.</p>\n<p>Не торопитесь с кадрированием. Аккуратная обрезка сейчас избавит от повторной работы, когда изображение в месте назначения будет выглядеть неправильно.</p>\n<p>Сначала посмотрите на фото целиком и решите, что в нём главное. Если главный объект теряется среди деталей, обрезка должна убрать лишнее, а не просто сделать кадр меньше.</p>\n<p>Проверьте, не срезает ли рамка что-то важное: руки, ноги, часть здания. Случайно срезанная деталь бросается в глаза сильнее, чем лишнее пространство по краям.</p>\n<p>Если сомневаетесь в плотности обрезки, оставьте чуть больше места. Свободное пространство вокруг объекта всегда можно убрать позже, а срезанное уже не вернуть.</p>\n<p>Попробуйте сделать два варианта обрезки: плотный и свободный. Сравнение рядом покажет, какой из них выглядит лучше, а выбор на глаз без сравнения часто оказывается случайным.</p>\n<p>Сохраните оба варианта под разными именами, если не можете решить сразу. Через день посмотрите на них свежим взглядом — правильный выбор обычно становится очевидным.</p>\n<ol>\n<li>Загрузите изображение: перетащите его в зону загрузки, выберите на устройстве или вставьте скриншот сочетанием Ctrl+V.</li>\n<li>Перетащите рамку выделения на часть, которую хотите сохранить, используя восемь маркеров, чтобы менять её размер с любой стороны или угла.</li>\n<li>Выберите предустановку соотношения сторон, например 1:1, 4:3 или 16:9, или оставьте свободный режим для произвольной формы.</li>\n<li>Проверьте размеры в пикселях на выходе, которые показывает инструмент, и убедитесь, что их достаточно для места назначения.</li>\n<li>Выберите формат экспорта и качество, затем нажмите «Скачать», чтобы сохранить обрезанное изображение.</li>\n</ol>\n<p>Откройте скачанный файл один раз перед использованием. Убедитесь, что кадрирование верное и ничто важное не срезано по краям.</p>\n<h2 id=\"dragging-the-selection-box\">Перетаскивание рамки выделения</h2>\n<p>Рамка выделения — это прямоугольник, который определяет вашу обрезку. Перетаскивайте внутри неё, чтобы переместить её, или тяните за один из восьми маркеров, чтобы изменить размер.</p>\n<p>Угловые маркеры изменяют размер сразу с двух сторон, и это самый быстрый способ кадрировать объект. Боковые маркеры настраивают только одну сторону, что полезно для точной доводки.</p>\n<p>Когда активна предустановка соотношения сторон, маркеры удерживают рамку в пропорции. Форма остаётся зафиксированной, пока меняется размер, поэтому квадрат остаётся квадратом.</p>\n<p>Всё за пределами рамки затемняется на рабочей области. Это затемнение помогает точно видеть, что сохранится, а что будет срезано.</p>\n<h2 id=\"choosing-an-aspect-ratio\">Выбор предустановки соотношения сторон</h2>\n<p>Выберите 1:1 для квадратного фото профиля или публикации в Instagram. Рамка остаётся идеально квадратной, пока вы её перетаскиваете, поэтому кадрирование остаётся последовательным.</p>\n<p>Выберите 4:3 для традиционной формы фото или обрезки документа. Она немного шире, чем высока, что подходит большинству печатных фото и отсканированных страниц.</p>\n<p>Выберите 16:9 для широкого баннера, миниатюры видео или слайда презентации. Широкая форма тянется через экраны, не оставляя пустого места.</p>\n<p>Используйте свободный режим, когда не подходит ни одна предустановка. Рамку можно перетащить в любую форму, что полезно для вырезания одного абзаца со страницы или детали с фото товара.</p>\n<p>Для историй в соцсетях выбирайте вертикальные пропорции 9:16. Квадратная обрезка в истории покажется маленькой, а вертикальная заполнит весь экран телефона.</p>\n<p>Для печати сначала узнайте точный формат бумаги, а потом выбирайте пропорцию. Обрезка под неверный формат означает либо белые полосы, либо срезанные края при печати.</p>\n<p>Если назначение неизвестно, начните со свободного режима и кадрируйте по композиции. Пропорцию под конкретную платформу всегда можно задать позже из исходного файла.</p>\n<h2 id=\"using-the-grid\">Использование сетки правила третей</h2>\n<p>Сетка делит рамку выделения на девять равных частей. Разместите объект на одной из линий или в точке пересечения, чтобы композиция выглядела естественнее.</p>\n<p>Для портрета поставьте глаза на верхнюю горизонтальную линию. Для пейзажа поставьте горизонт на верхнюю или нижнюю линию, а не посередине.</p>\n<p>Сетка также помогает заметить наклонённый объект. Если горизонт идёт по сетке диагонально, фото, возможно, нужно выпрямить до или после обрезки.</p>\n<p>Игнорируйте сетку, когда объект лучше работает по центру. Симметричное здание, логотип или портрет анфас часто выглядят лучше строго по центру.</p>\n<h2 id=\"zooming-for-detail\">Приближение для точного кадрирования</h2>\n<p>Приближайте изображение, когда нужная деталь мала. Особенность товара, лицо в толпе или одна строка текста — всё это выигрывает от более близкого взгляда перед постановкой рамки.</p>\n<p>Приближение не меняет качество на выходе. Оно лишь увеличивает предпросмотр, чтобы точнее расположить выделение, а экспорт по-прежнему использует исходные пиксели.</p>\n<p>После приближения перетащите изображение, чтобы отцентрировать деталь, затем подберите рамку вокруг неё. Проверьте показание размеров и убедитесь, что обрезка по-прежнему достаточно велика.</p>\n<p>Если приближенная обрезка слишком мала для места назначения, расширьте рамку или используйте исходное изображение большего размера. Крошечная обрезка, растянутая под баннер, будет выглядеть мягкой.</p>\n<h2 id=\"checking-dimensions\">Проверка размеров на выходе перед скачиванием</h2>\n<p>Инструмент показывает точные размеры в пикселях на выходе до скачивания. Это самая важная проверка во всём процессе, и она занимает две секунды.</p>\n<p>Сравните число с тем, что требует ваше место назначения. Фото профиля нуждается всего в нескольких сотнях пикселей, а баннеру сайта может потребоваться больше тысячи.</p>\n<p>Если обрезка слишком мала, расширьте рамку выделения. Более широкая рамка захватывает больше пикселей, что даёт месту назначения больше материала для работы.</p>\n<p>Кнопка «Выбрать всё» сбрасывает рамку на всё изображение. Используйте её, когда обрезали слишком сильно и хотите начать кадрирование заново с нуля.</p>\n<h2 id=\"choosing-export-format\">Выбор формата экспорта и качества</h2>\n<p>Выберите JPG для фото. Ползунок качества позволяет сбалансировать размер файла и детализацию, а значение около 85–90 сохраняет большинство фото чистыми на вид.</p>\n<p>Выберите PNG для скриншотов, логотипов и графики с текстом. PNG — без потерь, поэтому края букв остаются резкими, и он сохраняет прозрачность, когда она нужна.</p>\n<p>Выберите WebP, когда нужны маленькие файлы с хорошим качеством. Он хорошо подходит для изображений на сайте, хотя несколько старых систем до сих пор отвергают этот формат.</p>\n<p>Помните, что ползунок качества исчезает для PNG, потому что в PNG нет сжатия с потерями, которое можно настраивать. Это нормально, а не ошибка инструмента.</p>\n<p>Для фото, которые пойдут в мессенджер, выбирайте JPG с качеством 85. Файл получается лёгким и быстро отправляется, а разница с оригиналом на экране телефона незаметна.</p>\n<p>Для изображений на сайт лучше подходит WebP: при том же качестве файл заметно меньше, а страница загружается быстрее. Проверьте только, что ваша платформа его принимает.</p>\n<p>Если изображение содержит и фото, и текст, например афишу, выбирайте PNG. JPG размоет края букв, а PNG сохранит их резкими даже при маленьком размере шрифта.</p>\n<h2 id=\"cropping-screenshots\">Обрезка скриншота</h2>\n<p>Вставьте скриншот напрямую сочетанием Ctrl+V, чтобы пропустить шаг сохранения. Изображение сразу появляется в обрезчике, готовое к подрезке.</p>\n<p>Перетащите рамку вокруг того, что имеет значение: сообщения об ошибке, настройки или кнопки. Срежьте панель инструментов браузера, панель задач и любое пустое место.</p>\n<p>Экспортируйте скриншоты в PNG. Формат без потерь сохраняет мелкий текст читаемым, а сжатие JPG размывает края букв и делает их труднее для чтения.</p>\n<p>Назовите файл понятно, например error-message.png. Ясное имя облегчает поиск скриншота, когда вы прикрепляете его к сообщению или отчёту об ошибке.</p>\n<h2 id=\"cropping-on-mobile\">Обрезка на телефоне или планшете</h2>\n<p>Обрезчик работает с жестами пальцев на сенсорных экранах. Перетаскивайте рамку одним пальцем и сводите пальцы, чтобы приблизить изображение, когда нужен более близкий взгляд на кадрирование.</p>\n<p>Загружайте из галереи или снимайте фото напрямую. Инструмент обрабатывает файл так же, как на компьютере, а параметры экспорта идентичны.</p>\n<p>На маленьких экранах точное кадрирование даётся труднее, поэтому приближайте изображение перед постановкой рамки. Аккуратная обрезка на телефоне всё равно лучше торопливой на компьютере.</p>\n<p>Скачанные обрезки сохраняются в обычной папке загрузок. Оттуда их можно отправить в мессенджер, по почте или в соцсеть без лишних шагов.</p>\n<h2 id=\"troubleshooting\">Решение частых проблем с обрезкой</h2>\n<p>Если рамка выделения не меняет форму, проверьте, не зафиксирована ли предустановка соотношения сторон. Переключитесь в свободный режим, чтобы перетащить рамку в любую форму.</p>\n<p>Если скачанная обрезка выглядит размытой, выделение, вероятно, было слишком маленьким. Вернитесь к исходному файлу и расширьте рамку или начните с источника в более высоком разрешении.</p>\n<p>Если обрезка неверной формы для места назначения, проверьте предустановку пропорции. Обрезка 1:1 не подойдёт широкому баннеру, а обрезка 16:9 — квадратному слоту профиля.</p>\n<p>Если изображение выглядит тёмным за пределами рамки, это рабочая область затемняет зону, которая будет удалена. Это эффект предпросмотра, а не изменение вашего файла.</p>\n<p>Если рамка выделения прыгает при перетаскивании, проверьте, не включён ли режим привязки к пропорции. Отключите предустановку, и рамка станет двигаться свободно в любую сторону.</p>\n<p>Если скачанный файл оказался не того формата, посмотрите на выбранный формат экспорта. Инструмент сохраняет файл в выбранном формате, а не обязательно в исходном.</p>\n<p>Когда обрезка раз за разом получается не той, сделайте паузу и начните с кнопки «Выбрать всё». Сброс рамки к полному изображению часто быстрее, чем попытки починить неудачное выделение.</p>\n<h2 id=\"quick-tips\">Быстрые советы для лучшей обрезки</h2>\n<p>Каждый раз обрезайте из исходного файла. Повторная обрезка JPG, который уже был обрезан и сохранён, добавляет повреждений с каждым кругом.</p>\n<p>Оставляйте немного свободного места вокруг объекта. Лицо без запаса над головой выглядит стеснённо, а товар, касающийся края, выглядит как ошибка.</p>\n<p>Проверьте обрезку в полном размере перед скачиванием. Приблизьте лицо или текст и убедитесь, что ничто важное не стало мягким и не срезалось.</p>\n<p>Сохраняйте обрезанный файл под понятным именем. Имя вроде banner-16x9.png пригодится через месяцы, а имя вроде IMG_4821.png — нет.</p>\n<h2 id=\"cropping-product-photos\">Обрезка фото товаров</h2>\n<p>Фото товаров нуждаются в последовательном кадрировании, потому что страница магазина с несовпадающими обрезками выглядит небрежно. Обрезайте каждое фото товара под одну и ту же пропорцию, чтобы сетка выглядела аккуратно.</p>\n<p>Оставляйте немного места вокруг товара. Плотная обрезка, касающаяся краёв, делает предмет стеснённым, а небольшой отступ даёт ему возможность дышать.</p>\n<p>Используйте ровный фон и обрезайте любой беспорядок по краям. Чистый снимок товара на белом или светлом фоне продаётся лучше, чем перегруженный снимок с отвлекающими деталями.</p>\n<p>Для магазина с множеством товаров обрезайте пакетно: одна пропорция, одни отступы, один фон. Последовательность по всему каталогу важнее любой отдельно взятой идеальной обрезки.</p>\n<h2 id=\"cropping-for-email\">Обрезка изображений для почты</h2>\n<p>Изображения в письмах должны быть маленькими и правильно сформированными, потому что большое фото может сдвинуть текст с экрана или замедлить загрузку сообщения.</p>\n<p>Обрежьте изображение под ту часть, которая имеет значение, прежде чем прикреплять его. Полный скриншот с крошечной деталью в письме бесполезен, а плотная обрезка детали сразу понятна.</p>\n<p>Экспортируйте изображения для почты в JPG для фото и в PNG для скриншотов. Меньший размер файла делает письмо лёгким, а правильный формат сохраняет содержимое читаемым.</p>\n<p>Проверьте обрезанное изображение на телефоне перед отправкой. Большинство писем читают на мобильных, а обрезка, которая хорошо выглядит на компьютере, на экране телефона может оказаться слишком маленькой или слишком широкой.</p>\n<h2 id=\"cropping-and-accessibility\">Обрезка и доступность</h2>\n<p>Хорошая обрезка помогает всем, но важнее всего она для людей, которые просматривают изображения в увеличенном виде или с экранной лупой. Плотная обрезка важного содержимого легче для восприятия, чем широкий кадр, полный отвлекающих деталей.</p>\n<p>Когда обрезаете схему или график, держите подписи и легенду внутри кадра. График без подписей бессмыслен, какой бы резкой ни была обрезка.</p>\n<p>Для обучающих изображений обрезайте по одному шагу за раз. Одна ясная обрезка на шаг легче для восприятия, чем одно большое изображение, показывающее весь процесс сразу.</p>\n<p>Добавляйте короткую подпись или альтернативный текст, когда делитесь обрезанным изображением. Подпись объясняет, что показывает обрезка, и это помогает людям, которые не могут ясно видеть изображение.</p>\n<h2 id=\"saving-crop-presets\">Экономия времени с повторяемыми обрезками</h2>\n<p>Если вы часто обрезаете однотипные изображения, выработайте привычку. Используйте одну и ту же предустановку пропорции, один формат экспорта и одну схему именования каждый раз.</p>\n<p>Последовательный порядок экономит минуты на каждой обрезке. Вы перестаёте каждый раз заново решать, какую пропорцию и формат выбрать, и начинаете делать чистые обрезки, не задумываясь.</p>\n<p>Запишите пропорции, которые нужны вашим платформам. Короткий список на рабочем месте, например «профиль 1:1, баннер 16:9», убирает догадки из каждой сессии обрезки.</p>\n<p>Время от времени пересматривайте свои обрезки. Платформы меняют правила размеров, и пропорция, которая работала в прошлом году, может больше не подходить слоту, на который вы целитесь.</p>\n<p>Руководство по пропорциям читайте в статье <a href=\"/ru/blog/sootnosheniya-storon-pri-obrezke-1-1-4-3-16-9/\">Соотношения сторон при обрезке: 1:1, 4:3, 16:9 и другие</a>. Полный обзор — в статье <a href=\"/ru/blog/obrezka-izobrazheniy-polnoe-rukovodstvo/\">Обрезка изображений: полное руководство</a>, а если фото наклонено, сначала выпрямите его с помощью <a href=\"/ru/povernut-otrazit-izobrazhenie/\">инструмента поворота и отражения</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Как обрезать изображение в квадрат для Instagram?","answer":"Загрузите фото, выберите предустановку пропорции 1:1 и перетащите квадратную рамку на нужную часть. Держите объект по центру с небольшим запасом, проверьте размеры на выходе, затем скачайте в JPG для фото или в PNG для графики."},{"question":"Можно ли обрезать фото без установки приложения?","answer":"Да. Обрезчик полностью работает в браузере на любом устройстве, без установки и учётной записи. Загрузите изображение, перетащите рамку выделения, выберите пропорцию и скачайте результат. Ваше фото никогда не загружается на сервер."},{"question":"Какой формат лучше для скачивания обрезанного скриншота?","answer":"PNG, потому что он без потерь и сохраняет мелкий текст резким. Сжатие JPG размывает края букв, из-за чего скриншоты труднее читать. Используйте JPG только для обрезанных фото, где меньший размер файла важнее идеально точных краёв."},{"question":"Как обрезать человека или объект у края фото?","answer":"Перетащите рамку выделения так, чтобы ненужный человек или объект оказался за её пределами, затем скачайте обрезку. Затемнённая область на рабочей области показывает ровно то, что будет удалено. Если объект находится в середине кадра, обрезка его не уберёт, поэтому вместо этого размойте его."},{"question":"Почему моё обрезанное изображение размыто при загрузке?","answer":"Вероятно, рамка выделения была слишком маленькой, поэтому у обрезки меньше пикселей, чем требует место назначения. Вернитесь к исходному файлу, расширьте рамку и проверьте размеры на выходе перед скачиванием. Помогает и исходник в более высоком разрешении."},{"question":"Можно ли отменить обрезку после скачивания?","answer":"Нет, из скачанного файла — нельзя, так как обрезка навсегда удаляет срезанные пиксели. Сохраните исходное фото, чтобы обрезать его снова иначе. В инструменте используйте кнопку «Выбрать всё», чтобы сбросить рамку перед скачиванием."}];
